//! Fixtures for the CLI front-end crates.
//!
//! A [`CliFixture`] is a temp-directory database and search index laid out
//! the way a real install is — the index a sibling of the database file —
//! populated with a small, *fixed* catalog. The data is deliberately
//! hand-written rather than generated by [`livtet_data::seed_database`]:
//! command tests assert on rendered rows and snapshot real output, so the
//! titles, authors and formats have to be the same on every run.
//!
//! Shared from here rather than written inside one crate's `tests/` so that
//! `livtet-cli` and any later front-end (a TUI, say) assert against the same
//! catalog instead of each hand-rolling one.

use camino::{Utf8Path, Utf8PathBuf};
use livtet_data::{
    Kind, TestDb,
    entities::{authors, digital_inventory, edition_authors, editions, formats, works},
    orm::{ActiveModelTrait, DatabaseConnection, Set, SqlxSqliteConnector},
};
use livtet_types::DbId;

/// One edition in the fixture catalog, as the fixture knows it. Lets a test
/// name what it expects without re-deriving it from the seeding code.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FixtureEdition {
    pub id: DbId,
    pub title: &'static str,
    pub author: &'static str,
    pub format: &'static str,
    /// `Some` when the edition has a `digital_inventory` row with a file.
    pub file_path: Option<Utf8PathBuf>,
}

/// A temp-directory install: migrated database, built search index, and the
/// catalog that was written into them.
///
/// Holds the [`TestDb`], so the temp directory lives as long as the fixture.
/// Drop it and the directory goes with it.
pub struct CliFixture {
    /// Path to the SQLite file, for `sqlite:{db_path}` connection strings.
    pub db_path: Utf8PathBuf,
    /// Directory holding the Tantivy index, a sibling of `db_path`.
    pub index_dir: Utf8PathBuf,
    /// The catalog, in insertion order.
    pub editions: Vec<FixtureEdition>,
    db: TestDb,
}

impl CliFixture {
    /// Migrate a database, write the catalog, and build the index over it.
    pub async fn new() -> Self {
        let db = TestDb::new(&[Kind::Business])
            .await
            .expect("migrate test database");
        let dir = Utf8PathBuf::from(db.path());
        let db_path = dir.join("test.db");
        let index_dir = dir.join("search-index");

        let conn = SqlxSqliteConnector::from_sqlx_sqlite_pool(db.pool.clone());
        let editions = seed_catalog(&conn, &dir).await;

        livtet_search::SearchIndex::migrate_to(&index_dir, &conn)
            .await
            .expect("build search index");

        Self {
            db_path,
            index_dir,
            editions,
            db,
        }
    }

    /// A SeaORM connection to the fixture database, for assertions that read
    /// rows back directly.
    pub fn conn(&self) -> DatabaseConnection {
        SqlxSqliteConnector::from_sqlx_sqlite_pool(self.db.pool.clone())
    }

    /// The edition whose title is `title`.
    ///
    /// Panics when the catalog has no such edition, so a test that drifts
    /// from the fixture fails where it is wrong rather than on a later
    /// `unwrap`.
    pub fn edition(&self, title: &str) -> &FixtureEdition {
        self.editions
            .iter()
            .find(|e| e.title == title)
            .unwrap_or_else(|| {
                let known: Vec<&str> = self.editions.iter().map(|e| e.title).collect();
                panic!("no fixture edition titled {title:?}; catalog holds {known:?}")
            })
    }
}

/// Write the fixed catalog: two formats, two authors, and three editions
/// across two works, one of which has a file on disk.
async fn seed_catalog(conn: &DatabaseConnection, dir: &Utf8Path) -> Vec<FixtureEdition> {
    let now = livtet_types::now_primitive();

    let hardcover_id = DbId::new();
    let ebook_id = DbId::new();
    for (id, name) in [(hardcover_id, "Hardcover"), (ebook_id, "Ebook")] {
        formats::ActiveModel {
            id: Set(id),
            name: Set(name.to_string()),
            metadata_schema: Set(serde_json::Value::Null),
            progress_unit: Set(None),
        }
        .insert(conn)
        .await
        .expect("insert format");
    }

    let rothfuss_id = DbId::new();
    let jemisin_id = DbId::new();
    for (id, name) in [
        (rothfuss_id, "Patrick Rothfuss"),
        (jemisin_id, "N. K. Jemisin"),
    ] {
        authors::ActiveModel {
            id: Set(id),
            name: Set(name.to_string()),
        }
        .insert(conn)
        .await
        .expect("insert author");
    }

    // A file that actually exists, so `has_file` and the on-disk column are
    // true for the reason they would be in production.
    let file_path = dir.join("the-name-of-the-wind.epub");
    fs_err::write(&file_path, b"fixture epub").expect("write fixture file");

    let spec: Vec<(&'static str, &'static str, DbId, DbId, &'static str, bool)> = vec![
        (
            "The Name of the Wind",
            "Hardcover",
            hardcover_id,
            rothfuss_id,
            "Patrick Rothfuss",
            false,
        ),
        (
            "The Name of the Wind (Ebook)",
            "Ebook",
            ebook_id,
            rothfuss_id,
            "Patrick Rothfuss",
            true,
        ),
        (
            "The Fifth Season",
            "Hardcover",
            hardcover_id,
            jemisin_id,
            "N. K. Jemisin",
            false,
        ),
    ];

    let mut out = Vec::new();
    for (title, format_name, format_id, author_id, author_name, with_file) in spec {
        let work_id = DbId::new();
        works::ActiveModel {
            id: Set(work_id),
            title: Set(title.to_string()),
            description: Set(None),
            sort_title: Set(None),
            series_type: Set(None),
            language_id: Set(None),
            preferred_edition_id: Set(None),
            created_at: Set(now),
            updated_at: Set(None),
        }
        .insert(conn)
        .await
        .expect("insert work");

        let edition_id = DbId::new();
        editions::ActiveModel {
            id: Set(edition_id),
            work_id: Set(work_id),
            group_id: Set(None),
            title: Set(Some(title.to_string())),
            published_date: Set(None),
            format_id: Set(Some(format_id)),
            language_id: Set(None),
            notes: Set(None),
            description: Set(None),
            format_metadata: Set(None),
            created_at: Set(now),
            updated_at: Set(None),
        }
        .insert(conn)
        .await
        .expect("insert edition");

        edition_authors::ActiveModel {
            edition_id: Set(edition_id),
            author_id: Set(author_id),
            role: Set("author".to_string()),
        }
        .insert(conn)
        .await
        .expect("insert edition author");

        let file = if with_file {
            digital_inventory::ActiveModel {
                id: Set(DbId::new()),
                edition_id: Set(edition_id),
                file_path: Set(Some(file_path.to_string())),
                cover_path: Set(None),
                blurhash: Set(None),
                dominant_color: Set(None),
                file_hash: Set(None),
                file_size_bytes: Set(None),
                file_format: Set(Some("epub".to_string())),
                notes: Set(None),
                added_at: Set(now),
                updated_at: Set(None),
            }
            .insert(conn)
            .await
            .expect("insert digital inventory");
            Some(file_path.clone())
        } else {
            None
        };

        out.push(FixtureEdition {
            id: edition_id,
            title,
            author: author_name,
            format: format_name,
            file_path: file,
        });
    }
    out
}
